ext('c12_eng_ch10',[
C("✈️","पाठ की पृष्ठभूमि",["विदेशी यात्री की दृष्टि","भारत के विविध अनुभव","आतिथ्य और संस्कृति","निबंध/यात्रा-वृत्तांत शैली"],"यह पाठ एक विदेशी यात्री की आँखों से भारत को देखता है। लेखिका ने भारत की यात्रा के अपने अनुभव लिखे हैं, जिनमें लोगों का स्वागत, पहनावा, भोजन, शहरों और गाँवों का जीवन तथा संस्कृति की विविधता शामिल है। यात्रा-वृत्तांत पढ़ने का मज़ा यह है कि हमें अपनी जानी-पहचानी चीज़ों को एक नए नज़रिए से देखने का मौक़ा मिलता है। विदेशी की नज़र उन बातों को भी नोटिस करती है जिन्हें हम रोज़ देखकर अनदेखा कर देते हैं।"),
Q("यात्रा-वृत्तांत किसे कहते हैं?","यात्रा के अनुभवों, स्थानों और लोगों का वर्णन करने वाला लेखन","अपने शब्दों में सोचिए... जब कोई यात्री किसी जगह के अपने अनुभव, जैसे वहाँ के लोग, भोजन और दृश्य लिखता है, तो उसे यात्रा-वृत्तांत कहते हैं।"),
C("🏡","भारतीय आतिथ्य की परंपरा",["अतिथि देवो भव","अपरिचित का भी स्वागत","भोजन और चाय के साथ सत्कार","अपनापन"],"भारत में अतिथि को देवता के समान माना जाता है। लेखिका को यह बात अनुभव में बार-बार दिखी कि अजनबी का भी खुले मन से स्वागत किया जाता है। लोग चाय, भोजन और मिठाई के साथ आदर से मेहमान को बिठाते हैं। गाँव में तो पूरा मोहल्ला मेहमान का हाल पूछने आ जाता है। यह अपनापन विदेशी के लिए अनोखा अनुभव था। यही हमारी सांस्कृतिक पहचान है, जिसे हमें बनाए रखना चाहिए।"),
Q("भारतीय आतिथ्य की क्या विशेषता है?","अतिथि को देवता मानकर आदर, अपनापन और सत्कार देना","याद कीजिए... भारत में अपरिचित मेहमान का भी स्वागत खुले दिल से होता है। चाय, भोजन और अपनापन देना हमारी परंपरा है।"),
C("🏙️","नगर और गाँव का अंतर",["महानगर: तेज़ रफ़्तार","गाँव: धीमी, शांत ज़िंदगी","आधुनिकता और परंपरा","दोनों में अपनापन"],"लेखिका ने महानगरों और गाँवों के जीवन का अंतर देखा। महानगरों में ऊँची इमारतें, भीड़ और तेज़ रफ़्तार है, जबकि गाँव में खुला आसमान, खेत और शांत जीवन। शहर में आधुनिक सुविधाएँ ज़्यादा हैं तो गाँव में परंपराएँ ज़्यादा जीवित हैं। पर दोनों जगह लोगों में मेल-जोल और मदद की भावना दिखी। यह तुलना हमें अपने जीवन के दोनों पक्ष देखने का नज़रिया देती है।"),
Q("नगर और गाँव के जीवन में एक अंतर बताइए।","शहरों में भीड़ और तेज़ रफ़्तार है, गाँव में शांत और प्रकृति के निकट जीवन","अंतर सोचिए... बड़े शहर में हर कोई जल्दी में रहता है, जबकि गाँव में रफ़्तार धीमी और माहौल शांत होता है।"),
C("👩","भारतीय नारियों की भूमिका",["घर और परिवार की धुरी","शिक्षा और कार्यक्षेत्र में बढ़ती भागीदारी","पहनावे और परंपराएँ","बदलती भूमिका"],"लेखिका ने भारतीय महिलाओं की अनेक भूमिकाएँ देखीं। वे घर और परिवार की धुरी हैं, पर अब शिक्षा, नौकरी और व्यवसाय में भी आगे बढ़ रही हैं। उनका पहनावा, जैसे साड़ी और सूट, भारतीय संस्कृति की झलक देता है। ग्रामीण और शहरी, दोनों क्षेत्रों में महिलाओं की भूमिका बदल रही है। यह परिवर्तन समाज को मज़बूत बना रहा है और बेटियों की शिक्षा इसका आधार है।"),
Q("पाठ में भारतीय महिलाओं के बारे में क्या दिखाया गया है?","उनकी पारंपरिक भूमिका के साथ बदलती हुई आधुनिक भागीदारी","सोचिए... महिलाएँ परिवार की ज़िम्मेदारी निभाती हैं और साथ ही पढ़ाई तथा नौकरी में भी आगे बढ़ रही हैं। पाठ दोनों पक्ष दिखाता है।"),
C("🌈","विविधता में एकता",["भाषाएँ, धर्म, पहनावा","भोजन की विविधता","त्योहारों की रौनक","साझा संस्कृति"],"लेखिका को भारत की सबसे बड़ी ख़ूबी विविधता में एकता लगी। हर क्षेत्र की भाषा, भोजन और पहनावा अलग है, फिर भी लोग एक देश के नागरिक हैं। दीवाली, ईद, क्रिसमस और छठ जैसे त्योहारों में सब मिलकर हिस्सा लेते हैं। भोजन में उत्तर की रोटी से दक्षिण के डोसे तक विविधता है। यही रंगीन मिश्रण भारत को विशेष बनाता है और विदेशी यात्रियों को आकर्षित करता है।"),
Q("भारत को विविधता में एकता का देश क्यों कहते हैं?","क्योंकि भाषा, धर्म और रहन-सहन अलग होने पर भी लोग एक राष्ट्र की भावना से जुड़े हैं","कारण सोचिए... हमारे यहाँ अनेक भाषाएँ और धर्म हैं, फिर भी हम एक देश के नागरिक हैं और मिलकर त्योहार मनाते हैं।"),
C("🧐","लेखिका की दृष्टि और आज का संदर्भ",["ईमानदार अवलोकन","कभी-कभी कमियाँ भी दिखीं","पर्यटन का आर्थिक लाभ","संस्कृति के संरक्षण की ज़िम्मेदारी"],"लेखिका की दृष्टि ईमानदार है। उन्होंने अच्छाइयों के साथ कुछ कमियाँ, जैसे भीड़ और अव्यवस्था, भी देखीं। आज पर्यटन भारत की अर्थव्यवस्था का महत्वपूर्ण हिस्सा है। इसलिए हमारा कर्तव्य है कि हम स्वच्छता, आतिथ्य और अपनी विरासत को सँभालें। जब विदेशी हमारे देश की अच्छाइयाँ देखकर लौटते हैं, तो वे भारत के सद्भावना दूत बन जाते हैं।"),
C("✍️","उत्तर और निबंध के सुझाव",["परिचय: पाठ और लेखिका","मुख्य बिंदु: आतिथ्य, विविधता, महिलाएँ","अपना उदाहरण","निष्कर्ष: गर्व और ज़िम्मेदारी"],"इस पाठ पर उत्तर लिखते समय पहले लेखिका और पाठ का परिचय दीजिए। फिर आतिथ्य, नगर-गाँव का अंतर, महिलाओं की भूमिका और विविधता को बिंदुओं में लिखिए। अपने गाँव का कोई उदाहरण जोड़िए, जैसे मेहमान का स्वागत। अंत में निष्कर्ष लिखिए कि हमें अपनी संस्कृति पर गर्व करना और उसे सँभालना चाहिए। अपने शब्दों में लिखना अच्छा रहता है।"),
],7)
